import{_ as t}from"./chunks/website-studio.B1ViRGxP.js";import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Website Studio overview","description":"","frontmatter":{},"headers":[],"relativePath":"websites/studio-overview.md","filePath":"websites/studio-overview.md"}'),r={name:"websites/studio-overview.md"};function n(d,e,l,c,h,p){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="website-studio-overview" tabindex="-1">Website Studio overview <a class="header-anchor" href="#website-studio-overview" aria-label="Permalink to &quot;Website Studio overview&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release — source-reviewed draft</p><p>TransferBook+ v0.7.9 source baseline. Availability depends on installed release, permissions and configuration. Live publication is not established by this guide.</p></div><h2 id="illustrated-workspace" tabindex="-1">Illustrated workspace <a class="header-anchor" href="#illustrated-workspace" aria-label="Permalink to &quot;Illustrated workspace&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/website-studio.png"><img src="'+t+'" alt="Website Studio: page structure on the left, responsive canvas in the centre and property inspector on the right. The editor displays a saved local draft, not a published website."></a></p><p><em>Select the screenshot to open it at its original size. Use your browser’s Back button to return.</em></p><p><em>Website Studio: page structure on the left, responsive canvas in the centre and property inspector on the right. The editor displays a saved local draft, not a published website.</em></p><p>Staging capture, TransferBook+ v0.7.11; English UI. Illustrative test data. This image does not establish production availability. Identifiers masked.</p><h2 id="purpose-and-access" tabindex="-1">Purpose and access <a class="header-anchor" href="#purpose-and-access" aria-label="Permalink to &quot;Purpose and access&quot;">​</a></h2><p>Website Studio is the multi-page visual editor in TransferBook+. In the reference source, open <strong>Channels &amp; Governance → Website Studio</strong>, or select Website Studio from <strong>Settings → Website &amp; Themes</strong>. Use an authorized company context; the standalone design kit is a separate local workspace.</p><h2 id="understand-the-three-panels" tabindex="-1">Understand the three panels <a class="header-anchor" href="#understand-the-three-panels" aria-label="Permalink to &quot;Understand the three panels&quot;">​</a></h2><ol><li>The left panel manages websites, markets, pages, sections and navigation.</li><li>The central canvas renders the selected page and supports selecting and arranging sections.</li><li>The right inspector exposes block settings, Page &amp; SEO, Design, Brand &amp; Markets and History.</li></ol><h2 id="begin-safely" tabindex="-1">Begin safely <a class="header-anchor" href="#begin-safely" aria-label="Permalink to &quot;Begin safely&quot;">​</a></h2><p>Select a synthetic reference website or a permitted draft. Confirm the intended company, then select a page and a preview device. The built-in reference sites are examples, not verified operational customer websites.</p><h2 id="expected-result-and-troubleshooting" tabindex="-1">Expected result and troubleshooting <a class="header-anchor" href="#expected-result-and-troubleshooting" aria-label="Permalink to &quot;Expected result and troubleshooting&quot;">​</a></h2><p>A draft renders in the canvas without publishing a website. If no company context is available, do not bypass the warning; return to the authorized workspace. See <a href="./draft-storage.html">draft storage</a> before changing browser or company.</p><h2 id="editor-refinements-in-v0-7-10" tabindex="-1">Editor refinements in v0.7.10 <a class="header-anchor" href="#editor-refinements-in-v0-7-10" aria-label="Permalink to &quot;Editor refinements in v0.7.10&quot;">​</a></h2><p><strong>Status: source-reviewed staging release.</strong> In a compatible Website Studio workspace:</p><ol><li>Select Edit mode to arrange sections; switch to Preview to inspect the design without editor selection outlines and floating controls.</li><li>Search the section preset library and insert a preset after the selected section when appropriate.</li><li>Review the header and footer menus, header CTA and locale switcher; verify navigation in the canvas.</li><li>Use <code>Ctrl/Cmd+S</code> to save a draft, <code>Ctrl/Cmd+Z</code> to undo, <code>Ctrl/Cmd+Shift+Z</code> or <code>Ctrl+Y</code> to redo, and <code>Esc</code> to leave preview or clear selection. Confirm that the save succeeded.</li><li>Review desktop, tablet, mobile and 320 px narrow-mobile layouts, including the mobile menu and booking controls.</li></ol><p>The canvas is a preview, not proof of a live website. The standalone design kit has compatible editor refinements; its installed version must be checked independently. See <a href="./draft-storage.html">local drafts</a>.</p>',19)])])}const f=a(r,[["render",n]]);export{m as __pageData,f as default};
